PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE, password TEXT NOT NULL, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('paciente','psicologo','admin')), active INTEGER NOT NULL DEFAULT 1, profile TEXT NOT NULL DEFAULT '{}', quiz TEXT, crp TEXT NOT NULL DEFAULT '', verified INTEGER NOT NULL DEFAULT 0, review_note TEXT NOT NULL DEFAULT '', created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id);
CREATE TABLE IF NOT EXISTS likes (patient TEXT NOT NULL REFERENCES users(id), doctor TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','rejected')), created TEXT NOT NULL, PRIMARY KEY(patient,doctor));
CREATE INDEX IF NOT EXISTS idx_likes_doctor ON likes(doctor,status);
CREATE TABLE IF NOT EXISTS slots (id TEXT PRIMARY KEY, doctor TEXT NOT NULL REFERENCES users(id), starts TEXT NOT NULL, UNIQUE(doctor,starts));
CREATE TABLE IF NOT EXISTS appointments (id TEXT PRIMARY KEY, patient TEXT NOT NULL REFERENCES users(id), doctor TEXT NOT NULL REFERENCES users(id), starts TEXT NOT NULL, price INTEGER NOT NULL CHECK(price>=0), status TEXT NOT NULL CHECK(status IN ('scheduled','cancelled','completed')), payment TEXT NOT NULL DEFAULT 'pending', payment_id TEXT, meeting TEXT NOT NULL DEFAULT '', created TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS idx_appointments_doctor_busy ON appointments(doctor,starts) WHERE status!='cancelled';
CREATE UNIQUE INDEX IF NOT EXISTS idx_appointments_patient_busy ON appointments(patient,starts) WHERE status!='cancelled';
CREATE INDEX IF NOT EXISTS idx_appointments_patient ON appointments(patient,starts);
CREATE TABLE IF NOT EXISTS messages (id INTEGER PRIMARY KEY AUTOINCREMENT, patient TEXT NOT NULL REFERENCES users(id), doctor TEXT NOT NULL REFERENCES users(id), sender TEXT NOT NULL REFERENCES users(id), body TEXT NOT NULL, created TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_messages_pair ON messages(patient,doctor,id);
CREATE TABLE IF NOT EXISTS moods (id TEXT PRIMARY KEY, patient TEXT NOT NULL REFERENCES users(id), day TEXT NOT NULL, score INTEGER NOT NULL CHECK(score BETWEEN 1 AND 5), note TEXT NOT NULL, UNIQUE(patient,day));
CREATE TABLE IF NOT EXISTS notes (id TEXT PRIMARY KEY, doctor TEXT NOT NULL REFERENCES users(id), patient TEXT NOT NULL REFERENCES users(id), body TEXT NOT NULL, created TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_notes_pair ON notes(doctor,patient,created);
CREATE TABLE IF NOT EXISTS documents (id TEXT PRIMARY KEY, owner TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL, filename TEXT NOT NULL, mime TEXT NOT NULL, body TEXT NOT NULL, created TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_documents_owner ON documents(owner);
CREATE TABLE IF NOT EXISTS reviews (appointment TEXT PRIMARY KEY REFERENCES appointments(id), patient TEXT NOT NULL REFERENCES users(id), doctor TEXT NOT NULL REFERENCES users(id), rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5), body TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tickets (id TEXT PRIMARY KEY, owner TEXT NOT NULL REFERENCES users(id), subject TEXT NOT NULL, body TEXT NOT NULL, reply TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'open', created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS articles (id TEXT PRIMARY KEY, title TEXT NOT NULL, body TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit (id INTEGER PRIMARY KEY AUTOINCREMENT, actor TEXT NOT NULL, action TEXT NOT NULL, target TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS resets (token TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires INTEGER NOT NULL);
